/* @autogenerated */
package net.civeira.phylax.feature.oauth.consent.infrastructure.driven;

import java.time.OffsetDateTime;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClientReference;
import net.civeira.phylax.feature.access.oauthclient.domain.gateway.OauthClientFilter;
import net.civeira.phylax.feature.access.oauthclient.domain.gateway.OauthClientQueryRepositoryGateway;
import net.civeira.phylax.feature.access.userscopeconsent.domain.UserScopeConsent;
import net.civeira.phylax.feature.access.userscopeconsent.domain.UserScopeConsentChangeSet;
import net.civeira.phylax.feature.access.userscopeconsent.domain.gateway.UserScopeConsentCommandRepositoryGateway;
import net.civeira.phylax.feature.access.userscopeconsent.domain.gateway.UserScopeConsentFilter;
import net.civeira.phylax.feature.access.userscopeconsent.domain.gateway.UserScopeConsentQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserFilter;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserQueryRepositoryGateway;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.feature.oauth.client.infrastructure.driven.OauthClientPolicy;
import net.civeira.phylax.feature.oauth.consent.domain.ClientConsentSummary;
import net.civeira.phylax.feature.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.feature.oauth.consent.domain.gateway.ScopeApprovalGateway;
import net.civeira.phylax.feature.oauth.consent.domain.gateway.ScopesConsentGateway;

/**
 * ACL adapter that bridges the OIDC scope consent protocol port to the Access bounded context.
 *
 * Resolves username → User UID and clientId → OauthClient UID before operating on UserScopeConsent
 * records. Also implements ScopeApprovalGateway so a single bean handles both the persistence port
 * and the OIDC step port.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ScopesConsentAdapter implements ScopesConsentGateway, ScopeApprovalGateway {

  private final UserQueryRepositoryGateway users;
  private final TenantQueryRepositoryGateway tenants;
  private final OauthClientQueryRepositoryGateway clients;
  private final UserScopeConsentQueryRepositoryGateway consentRead;
  private final UserScopeConsentCommandRepositoryGateway consentWrite;

  // -------------------------------------------------------------------------
  // ScopesConsentGateway
  // -------------------------------------------------------------------------

  @Override
  public List<ScopePermission> pendingScopes(String tenant, String username, String clientId,
      List<String> scopes) {
    if (scopes.isEmpty()) {
      return List.of();
    }
    User user = user(tenant, username).orElse(null);
    if (user == null) {
      return toPermissions(scopes);
    }
    OauthClient client = client(tenant, clientId).orElse(null);
    if (client == null) {
      return toPermissions(scopes);
    }
    Set<String> granted = loadGrantedScopes(user, client);
    return scopes.stream().filter(s -> !granted.contains(s)).map(this::toPermission).toList();
  }

  @Override
  public void storeAcceptedScopes(String tenant, String username, String clientId,
      List<String> scopes) {
    if (scopes.isEmpty()) {
      return;
    }
    User user = user(tenant, username).orElse(null);
    if (user == null) {
      return;
    }
    OauthClient client = client(tenant, clientId).orElse(null);
    if (client == null) {
      return;
    }
    persistScopes(user, client, scopes);
  }

  @Override
  public List<ClientConsentSummary> listGrantedByUser(String tenant, String username) {
    User user = user(tenant, username).orElse(null);
    if (user == null) {
      return List.of();
    }
    List<UserScopeConsent> consents =
        consentRead.list(UserScopeConsentFilter.builder().user(user).build()).stream()
            .filter(c -> Boolean.TRUE.equals(c.isGranted())).toList();

    Map<String, List<UserScopeConsent>> byClient =
        consents.stream().collect(Collectors.groupingBy(UserScopeConsent::getOauthClientUid));

    return byClient.entrySet().stream().map(entry -> {
      String clientUid = entry.getKey();
      List<UserScopeConsent> clientConsents = entry.getValue();
      OauthClient client =
          clients.find(OauthClientFilter.builder().uid(clientUid).build()).orElse(null);
      List<String> scopes = clientConsents.stream().map(c -> c.getScope().orElse(null))
          .filter(s -> s != null).sorted().toList();
      OffsetDateTime lastAt = clientConsents.stream().map(c -> c.getDecisionAt().orElse(null))
          .filter(d -> d != null).max(OffsetDateTime::compareTo).orElse(null);
      return new ClientConsentSummary(clientUid, client != null ? client.getCode() : clientUid,
          client != null ? client.getClientName() : Optional.empty(), scopes,
          Optional.ofNullable(lastAt));
    }).toList();
  }

  @Override
  public void revokeClientConsent(String tenant, String username, String clientUid) {
    User user = user(tenant, username).orElse(null);
    if (user == null) {
      return;
    }
    List<UserScopeConsent> consents = consentWrite.listForUpdate(UserScopeConsentFilter.builder()
        .user(user).oauthClient(OauthClientReference.of(clientUid)).build());
    for (UserScopeConsent consent : consents) {
      consentWrite.delete(consent.delete());
    }
  }

  @Override
  public void revokeScopeConsent(String tenant, String username, String clientUid, String scope) {
    User user = user(tenant, username).orElse(null);
    if (user == null) {
      return;
    }
    consentWrite
        .listForUpdate(UserScopeConsentFilter.builder().user(user)
            .oauthClient(OauthClientReference.of(clientUid)).build())
        .stream().filter(c -> scope.equals(c.getScope().orElse(null)))
        .forEach(c -> consentWrite.delete(c.delete()));
  }

  // -------------------------------------------------------------------------
  // ScopeApprovalGateway — delegates to the consent logic above
  // -------------------------------------------------------------------------

  @Override
  public List<ScopePermission> pendingApprovals(String tenant, String username, String clientId,
      List<String> requestedScopes, List<AuthenticationChallenge> completedChallenges) {
    return pendingScopes(tenant, username, clientId, requestedScopes);
  }

  @Override
  public void storeApprovedScopes(String tenant, String username, String clientId,
      List<String> acceptedScopes) {
    storeAcceptedScopes(tenant, username, clientId, acceptedScopes);
  }

  @Override
  public void withdrawScopes(String tenant, String username, String clientId, List<String> scopes) {
    if (scopes.isEmpty()) {
      return;
    }
    Optional<User> user = user(tenant, username);
    Optional<OauthClient> client = client(tenant, clientId);
    if (user.isEmpty() || client.isEmpty()) {
      return;
    }
    consentWrite
        .listForUpdate(
            UserScopeConsentFilter.builder().user(user.get()).oauthClient(client.get()).build())
        .stream().filter(c -> scopes.contains(c.getScope().orElse(null)))
        .forEach(c -> consentWrite.delete(c.delete()));
  }

  // -------------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------------

  /**
   * The user of the tenant: a namesake in another tenant is a different person (task 0.5).
   */
  private Optional<User> user(String tenant, String username) {
    return tenants.find(TenantFilter.builder().name(tenant).build())
        .flatMap(t -> users.find(UserFilter.builder().name(username).tenant(t).build()));
  }

  /**
   * The client the tenant sees for a code: its own, else a global one (task 0.5).
   */
  private Optional<OauthClient> client(String tenant, String clientId) {
    return tenants.find(TenantFilter.builder().name(tenant).build()).flatMap(t -> OauthClientPolicy
        .select(clients.list(OauthClientFilter.builder().code(clientId).build()), t.getUid()));
  }

  private Set<String> loadGrantedScopes(User user, OauthClient client) {
    return consentRead.list(UserScopeConsentFilter.builder().user(user).oauthClient(client).build())
        .stream().filter(c -> Boolean.TRUE.equals(c.isGranted()))
        .map(c -> c.getScope().orElse(null)).filter(s -> s != null).collect(Collectors.toSet());
  }

  private void persistScopes(User user, OauthClient client, List<String> scopes) {
    Set<String> existing = loadGrantedScopes(user, client);
    for (String scope : scopes) {
      if (!existing.contains(scope)) {
        UserScopeConsent consent =
            UserScopeConsent.create(new UserScopeConsentChangeSet().newUid().user(user)
                .oauthClient(client).scope(scope).granted(true).decisionAt(OffsetDateTime.now()));
        consentWrite.create(consent);
      }
    }
  }

  private List<ScopePermission> toPermissions(List<String> scopes) {
    return scopes.stream().map(this::toPermission).toList();
  }

  private ScopePermission toPermission(String scope) {
    return ScopePermission.builder().scope(scope).required(false).label(scope).description(scope)
        .build();
  }
}
